SELECT id, tenant_id, order_id, user_id, user_name, dish_id, dish_name,
       star_rating, content, images, reply_content, reply_time, status,
       create_time, update_time, create_user, update_user
FROM dish_evaluation
WHERE tenant_id = #{tenantId}
  AND dish_id = #{dishId}

    AND status = #{status}


    AND status = 1

ORDER BY create_time DESC

SELECT id, tenant_id, order_id, user_id, user_name, dish_id, dish_name,
       star_rating, content, images, reply_content, reply_time, status,
       create_time, update_time, create_user, update_user
FROM dish_evaluation
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT AVG(star_rating)
FROM dish_evaluation
WHERE tenant_id = #{tenantId}
  AND dish_id = #{dishId}
  AND status = 1

SELECT COUNT(*)
FROM dish_evaluation
WHERE tenant_id = #{tenantId}
  AND status = #{status}
